benchmarks = [
 ('Little Coders: Intro to Coding · 25079','NKCC · Coding with Kids · 2026/9/21–11/9','5–7 歲 · 8 × 60 分鐘','Ages 5–7 · 8 × 60 min','$234 / $281','$29.25／堂；$24.38／50 分鐘','$29.25/session; $24.38/50 min'),
 ('Wilderness Medicine · 24865','NKCC · Little Medical School · 2026/9/17–11/19','7–11 歲 · 10 × 60 分鐘','Ages 7–11 · 10 × 60 min','$380 / $456','$38／堂；$31.67／50 分鐘','$38/session; $31.67/50 min'),
 ('Elementary Tumbling 1 · 24971','NKCC · 2026/9/16–10/21','5–7 歲 · 6 × 45 分鐘','Ages 5–7 · 6 × 45 min','$72 / $86','$12／堂；$13.33／50 分鐘','$12/session; $13.33/50 min')]
